// ARVEXQ live relay: live odds only. Stateless, no D1, no prediction storage.
// Detached from workers/web.mjs so it keeps running on its own after the app
// itself moves to GitHub Pages. Serves only /api/live-odds/*; every other
// path is 404 (delivery is Pages' job, not the relay's).
// Assets bundled with this worker (dist-live-relay/) carry only
// odds-sources/ and odds-backups/, generated by the same build_sources code
// as the main dist, so manifest verification is unchanged.
import {sourceOdds} from './live_odds.mjs';
import {savedOdds} from './saved_odds.mjs';
// The handler below is the original web.mjs live-odds branch, unchanged.
// The default export wraps it to add CORS: once the app is served from
// GitHub Pages it calls this relay cross-origin, and browsers would block
// the responses without an explicit grant. The endpoint is a public
// read-only odds feed, so the grant is '*'.
async function handle(request,env,ctx){
    const url=new URL(request.url);
    if(!url.pathname.startsWith('/api/live-odds/'))
      return new Response('Not Found',{status:404,headers:{'Cache-Control':'no-store'}});
    if(request.method!=='GET')return new Response('Method not allowed',{status:405});
    let source,date,retainedKey;
    try{
      const id=decodeURIComponent(url.pathname.slice('/api/live-odds/'.length));
      const match=/^(?:jra|nar)-(\d{4}-\d{2}-\d{2})-[^-/?]+-\d{2}$/.exec(id);
      if(!match)return Response.json({ok:false,error:'invalid race id'},{status:400});
      const asset=await env.ASSETS.fetch(new Request(url.origin+'/odds-sources/'+match[1]+'.json'));
      if(!asset.ok)throw Error('source manifest absent');
      const manifest=await asset.json();source=manifest.races&&manifest.races[id];date=match[1];
      if(manifest.version!=='arvexq-odds-sources-v1'||manifest.date!==match[1]||!source||source.id!==id||source.date!==match[1])
        return Response.json({ok:false,error:'verified source absent'},{status:404});
      const key=new Request(url.origin+url.pathname),cache=caches.default;
      const cached=await cache.match(key);if(cached&&!url.searchParams.has('force'))return cached;
      retainedKey=new Request(url.origin+url.pathname+'?last-acquired=1');
      const result=await sourceOdds(source);
      // Relay cache: 30s (user-set range 30-60s). Retained copy stays 7 days
      // so a source outage falls back to the last acquired odds, never to
      // invented prices.
      const response=Response.json(result,{headers:{'Cache-Control':'public, max-age=30'}});
      const retained=response.clone();retained.headers.set('Cache-Control','public, max-age=604800');
      ctx.waitUntil(Promise.all([cache.put(key,response.clone()),cache.put(retainedKey,retained)]));return response;
    }catch(_error){
      if(source){
        try{
          const retained=retainedKey&&await caches.default.match(retainedKey);
          const body=retained?{...(await retained.json()),oddsStatus:'saved',refreshFailed:true}:await savedOdds(env,url.origin,date,source);
          if(body)return Response.json(body,{headers:{'Cache-Control':'no-store'}});
        }catch{}
      }
      // For a verified race, source unavailability is data missingness, not an invalid page.
       // Keep 'ok:false' and empty odds: never invent a price or suppress the failure.
       return Response.json(source?{ok:false,race_id:source.id,odds:[],oddsStatus:'unavailable',refreshFailed:true,error:'official odds unavailable'}:{ok:false,error:'official odds source manifest unavailable',odds:[]},
         {status:source?200:503,headers:{'Cache-Control':'no-store'}});
    }
}
export default {
  async fetch(request,env,ctx){
    if(request.method==='OPTIONS')
      return new Response(null,{status:204,headers:{
        'Access-Control-Allow-Origin':'*',
        'Access-Control-Allow-Methods':'GET, OPTIONS',
        'Access-Control-Max-Age':'86400',
        'Cache-Control':'no-store'}});
    const response=await handle(request,env,ctx);
    const headers=new Headers(response.headers);
    headers.set('Access-Control-Allow-Origin','*');
    return new Response(response.body,{status:response.status,statusText:response.statusText,headers});
  }
};
